1099: function ConvertFrom-StructuredReply {
1100:     param([string]$Text, [string]$Purpose = '', $PriorFindings = @())
1101:     $result = [pscustomobject]@{
1102:         Valid                  = $false
1103:         Reply                  = $null
1104:         Errors                 = [string[]]@()
1105:         ValidationError        = ''
1106:         Verdict                = ''
1107:         VerdictInvalid         = $false
1108:         VerdictProblem         = ''
1109:         UncheckedPriorBlockers = [string[]]@()
1110:         BlockerCount           = 0
1111:         Fenced                 = $false
1112:     }
1113:     $t = ''
1114:     if ($Text) { $t = $Text.Trim() }
1115:     if (-not $t) {
1116:         $result.ValidationError = 'empty reply'
1117:         $result.Errors = [string[]]@('empty reply')
1118:         return $result
1119:     }
1120:     $fence = [regex]::Match($t, '^```[A-Za-z0-9_-]*[ \t]*\r?\n(?<body>[\s\S]*?)\r?\n[ \t]*```$')
1121:     if ($fence.Success) { $t = $fence.Groups['body'].Value.Trim(); $result.Fenced = $true }
1122:     $obj = $null
1123:     try {
1124:         $obj = ConvertFrom-Json -InputObject $t
1125:     } catch {
1126:         $msg = ConvertTo-OneLine $_.Exception.Message
1127:         if ($msg.Length -gt 120) { $msg = $msg.Substring(0, 120) + '...' }
1128:         $result.ValidationError = "not valid JSON: $msg"
1129:         $result.Errors = [string[]]@($result.ValidationError)
1130:         return $result
1131:     }
1132:     try {
1133:         $errs = Test-StructuredReply -Reply $obj
1134:         if ($errs.Count -gt 0) {
1135:             $result.Errors = $errs
1136:             $result.ValidationError = $errs[0]
1137:             return $result
1138:         }
1139:         $norm = ConvertTo-NormalizedReply -Reply $obj
1140:         $sem = Test-ReplySemantics -Reply $norm -Purpose $Purpose -PriorFindings $PriorFindings
1141:     } catch {
1142:         $msg = ConvertTo-OneLine $_.Exception.Message
1143:         if ($msg.Length -gt 160) { $msg = $msg.Substring(0, 160) + '...' }
1144:         $result.ValidationError = "could not validate the reply: $msg"
1145:         $result.Errors = [string[]]@($result.ValidationError)
1146:         return $result
1147:     }
1148:     $result.Valid = $true
1149:     $result.Reply = $norm
1150:     $result.BlockerCount = @($norm.findings | Where-Object { $_.severity -eq 'blocker' }).Count
1151:     $result.UncheckedPriorBlockers = $sem.Unchecked
1152:     if ($sem.Problems.Count -gt 0) {
1153:         $result.VerdictInvalid = $true
1154:         $result.ValidationError = ($sem.Problems -join '; ')
1155:         $result.VerdictProblem = ($sem.Short -join '; ')
1156:         $result.Verdict = ''
