1343: function Format-StructuredStatusLine {
1344:     param($Parse, $Ingest, [string]$ReplyJsonRel = '')
1345:     if (-not $Parse.Valid) {
1346:         $line = "Structured reply: INVALID ($($Parse.ValidationError)) - raw text kept; no findings recorded."
1347:         if ($ReplyJsonRel) { $line += " Raw last message: ``$ReplyJsonRel``." }
1348:         return $line
1349:     }
1350:     if ($Parse.VerdictInvalid) {
1351:         $verdictText = "Verdict: (invalid: $($Parse.VerdictProblem))."
1352:     } else {
1353:         $reason = Close-Sentence $Parse.Reply.verdict_reason
1354:         $verdictText = "Verdict: $($Parse.Verdict)"
1355:         if ($reason) { $verdictText += " - $reason" } else { $verdictText += '.' }
1356:     }
1357:     $n = @($Parse.Reply.findings).Count
1358:     if ($n -gt 0) {
1359:         $findingsText = "Findings: $(Format-SeverityCounts $Ingest.Counts) ($(Format-IdRange $Ingest.NewIds), tracked in ``findings.json``)."
1360:     } else {
1361:         $findingsText = 'Findings: none.'
1362:     }
1363:     $line = "$verdictText $findingsText"
1364:     if ($ReplyJsonRel) { $line += " Structured reply: ``$ReplyJsonRel``." }
1365:     return $line
1366: }
